// cards_sex_coach_tips.js — данные для 9-го модуля игры «Предложи партнеру»:
// топ-100 советов сексологов и секс-коучей о том, как улучшить сексуальную
// жизнь в паре. Формат такой же, как у cards_desires_women.js — без фото,
// без forWhom, с рейтингами (см. renderPhotoCard в core.js).
// level (здесь всегда 9), rank — условный номер по популярности совета,
// title — короткая формулировка, text — поясняющее предложение,
// womenRating/menRating — насколько ценным считают этот совет женщины и
// мужчины в среднем (0-10).

const SEX_COACH_TIPS_CARDS = [
  { level: 9, rank: 1, title: 'Говорите о желаниях вслух', text: 'Партнёр не может надёжно угадывать ваши желания по намёкам. Спокойно говорите, какие прикосновения, темп и действия вам приятны, а что лучше изменить или прекратить.', womenRating: 9, menRating: 9 },
{ level: 9, rank: 2, title: 'Не спешите к финалу', text: 'Дайте достаточно времени поцелуям, прикосновениям и другим ласкам, чтобы возбуждение постепенно нарастало. Темп должен подходить обоим, а продолжительная прелюдия не является обязательством.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 3, title: 'Спрашивайте «как тебе?»', text: 'Короткий вопрос во время близости помогает понять ощущения партнёра и вовремя изменить темп, давление или выбранный способ ласк.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 4, title: 'Уделяйте время объятиям после', text: 'После близости оставайтесь рядом, обнимайтесь, разговаривайте или просто отдыхайте вместе. Такое внимание помогает сохранить эмоциональный контакт и понять состояние друг друга.', womenRating: 9, menRating: 6 },
{ level: 9, rank: 5, title: 'Изучайте тело партнёра без спешки', text: 'Постепенно обращайте внимание на реакцию партнёра на прикосновения к разным зонам тела. Не существует универсальной карты ощущений, поэтому лучше спрашивать и наблюдать за обратной связью.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 6, title: 'Не сравнивайте с порно', text: 'Порно является постановочным контентом и не показывает обычные тела, реакции или темп близости. Ориентируйтесь на реальные ощущения, согласие и комфорт вашей пары.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 7, title: 'Планируйте свидания даже спустя годы', text: 'Регулярно выделяйте время только для двоих без телефонов и бытовых задач. Совместные свидания поддерживают эмоциональную связь и дают возможность общаться вне повседневной рутины.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 8, title: 'Учитывайте разную скорость возбуждения', text: 'Партнёрам может требоваться разное время для возбуждения. Не сокращайте прелюдию из-за спешки и ориентируйтесь на готовность обоих, а не на усреднённые ожидания.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 9, title: 'Не критикуйте во время близости', text: 'Не высмеивайте тело, реакцию или действия партнёра в уязвимый момент. Если что-то не подходит, используйте спокойную просьбу или обсудите это позже.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 10, title: 'Пробуйте новое постепенно', text: 'Начинайте с небольших изменений, которые интересны обоим, и заранее обсуждайте границы. Любой эксперимент можно остановить, если он вызывает тревогу, боль или дискомфорт.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 11, title: 'Обсуждайте границы заранее', text: 'До эксперимента договоритесь, что точно подходит, что вызывает сомнения и что исключено. Заранее выбранный стоп-сигнал помогает быстро остановить действие без объяснений.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 12, title: 'Не воспринимайте спад желания лично', text: 'Желание может снижаться из-за стресса, усталости, здоровья, лекарств или жизненных обстоятельств. Это не обязательно означает потерю влечения к партнёру.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 13, title: 'Держите телефоны подальше от спальни', text: 'Уберите уведомления и экраны, чтобы не отвлекаться на рабочие и бытовые дела. Это помогает обоим сосредоточиться на разговоре, прикосновениях и собственных ощущениях.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 14, title: 'Меняйте обстановку время от времени', text: 'Иногда перенесите близость в другую комнату или измените освещение и музыку. Новизна не обязана быть экстремальной, чтобы привычный сценарий ощущался иначе.', womenRating: 7, menRating: 8 },
{ level: 9, rank: 15, title: 'Практикуйте несексуальные прикосновения', text: 'Объятия, поцелуи, массаж и прикосновения в течение дня поддерживают ощущение близости, не создавая обязательства продолжать секс.', womenRating: 9, menRating: 6 },
{ level: 9, rank: 16, title: 'Обсуждайте несовпадение либидо открыто', text: 'Разный уровень желания встречается часто и не означает, что один из партнёров неправ. Обсуждайте потребности, отказ от давления и формы близости, которые подходят обоим.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 17, title: 'Уделяйте внимание качеству поцелуев', text: 'Не торопитесь и замечайте, какой темп, давление и продолжительность приятны партнёру. Поцелуи могут быть самостоятельной формой близости, а не только подготовкой к сексу.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 18, title: 'Не бойтесь пауз в процессе', text: 'Пауза, смех, глоток воды или совместное дыхание не означают неудачу. Остановитесь, если нужно восстановить комфорт, и продолжайте только при желании обоих.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 19, title: 'Изучите зоны за пределами гениталий', text: 'Шея, спина, плечи, уши, руки и бёдра могут быть чувствительными зонами, но реакция индивидуальна. Начинайте мягко и спрашивайте, что приятно.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 20, title: 'Практикуйте осознанность во время близости', text: 'Сосредоточьтесь на дыхании, прикосновениях и телесных ощущениях, возвращая внимание от рабочих мыслей и тревоги к текущему моменту.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 21, title: 'Заботьтесь о смазке', text: 'Используйте подходящий лубрикант при сухости или трении и добавляйте его по необходимости. Проверьте совместимость средства с презервативом и игрушкой.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 22, title: 'Тренируйте мышцы тазового дна', text: 'Упражнения тазового дна могут помогать некоторым людям с контролем мочеиспускания, ощущениями и сексуальной функцией. Выполняйте их правильно и не перенапрягайте мышцы.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 23, title: 'Делитесь фантазиями без осуждения', text: 'Выслушайте фантазию партнёра без насмешек и не воспринимайте её как требование. Обсуждение не означает обязательное воплощение, а согласие должно быть взаимным.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 24, title: 'Не держите счёт, кто инициирует', text: 'Подсчёт инициативы может превратить близость в соревнование или обязанность. Лучше обсуждать потребности и иногда самостоятельно предлагать друг другу время для нежности.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 25, title: 'Заботьтесь о сне', text: 'Недосып снижает энергию, настроение и у некоторых людей — сексуальное желание. Стабильный сон часто полезнее попыток компенсировать усталость дополнительными стимулами.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 26, title: 'Ограничивайте алкоголь перед близостью', text: 'Алкоголь может временно снизить тревогу, но избыток ухудшает чувствительность, возбуждение и способность дать осознанное согласие. Оба партнёра должны оставаться в ясном сознании.', womenRating: 6, menRating: 7 },
{ level: 9, rank: 27, title: 'Следите за общим уровнем стресса', text: 'Хронический стресс может снижать желание, мешать возбуждению и усиливать раздражительность. Обсуждайте не только секс, но и нагрузку, сон, отдых и поддержку.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 28, title: 'Создавайте атмосферу заранее', text: 'Уберите лишние вещи, приглушите свет, включите музыку и отключите уведомления, если это нравится обоим. Подготовка помогает переключиться от бытовых дел к совместному времени.', womenRating: 9, menRating: 5 },
{ level: 9, rank: 29, title: 'Обсуждайте, что понравилось после', text: 'После близости назовите одну приятную деталь и одну вещь, которую можно изменить в следующий раз. Говорите о собственных ощущениях, не превращая разговор в оценку партнёра.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 30, title: 'Не гонитесь за одновременным оргазмом', text: 'Одновременный оргазм не является обязательной целью и не определяет качество секса. Партнёры могут получать удовольствие в разное время и разными способами.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 31, title: 'Уважайте отказ без обид', text: 'Спокойная реакция на «не сегодня» сохраняет доверие и чувство безопасности. Отказ не требует наказания, уговоров или объяснений, а согласие должно оставаться добровольным.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 32, title: 'Проверяйте согласие на новое заранее', text: 'Перед новой практикой убедитесь, что оба понимают, что будет происходить, и действительно готовы. Согласие можно изменить в любой момент.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 33, title: 'Не забывайте про юмор в постели', text: 'Лёгкий совместный смех может снять напряжение, если никого не высмеивают. Если ситуация стала неловкой, можно сделать паузу и спокойно обсудить её.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 34, title: 'Разговаривайте о контрацепции открыто', text: 'Заранее обсудите способ контрацепции, защиту от ИППП и ответственность каждого партнёра. Это снижает тревогу и помогает принимать решения без спешки.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 35, title: 'Балансируйте быстрое и неспешное', text: 'Быстрая близость и долгий вечер могут быть одинаково ценными в разных обстоятельствах. Важно, чтобы выбранный формат подходил обоим и не воспринимался как обязанность.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 36, title: 'Делайте комплименты партнёру', text: 'Говорите конкретно, что вам нравится во внешности, прикосновениях и поведении партнёра. Искренние комплименты могут поддерживать уверенность и эмоциональную близость.', womenRating: 9, menRating: 8 },
{ level: 9, rank: 37, title: 'Заботьтесь о гигиене без напоминаний', text: 'Душ, чистые руки, свежая одежда и уход за игрушками помогают обоим чувствовать себя увереннее. При необычном запахе, боли или выделениях близость лучше отложить и обратиться к врачу.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 38, title: 'Не сравнивайте партнёра с бывшими', text: 'Сравнения могут разрушать доверие и самооценку. Обсуждайте собственные ощущения и желания, не превращая прошлые отношения в критерий оценки нынешнего партнёра.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 39, title: 'Пробуйте разные позы регулярно', text: 'Иногда смена позы меняет давление, угол и доступность стимуляции. Выбирайте только удобные варианты и прекращайте, если появляется боль или неустойчивость.', womenRating: 7, menRating: 8 },
{ level: 9, rank: 40, title: 'Разговаривайте о фантазиях заранее, не в моменте', text: 'Обсуждение вне спальни даёт обоим время спокойно подумать и обозначить границы. Это снижает неловкость и не заставляет принимать решение под влиянием возбуждения.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 41, title: 'Понимайте рефрактерный период мужчины', text: 'После оргазма мужчине может потребоваться время, прежде чем снова появится возбуждение или эрекция. Продолжительность индивидуальна и не означает потерю интереса к партнёрше.', womenRating: 7, menRating: 8 },
{ level: 9, rank: 42, title: 'Не рассматривайте секс только как обязанность', text: 'Близость не должна быть долгом, наградой или способом избежать конфликта. Оставляйте место для желания, отдыха, объятий и честного отказа.', womenRating: 8, menRating: 8 },
{ level: 9, rank: 43, title: 'Ищите баланс между спонтанностью и планированием', text: 'Спонтанность подходит не всем и не всегда. При детях, сменной работе или высокой нагрузке запланированное время для близости может снизить стресс и помочь сохранить контакт.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 44, title: 'Обращайтесь к специалисту при затянувшихся сложностях', text: 'Сексолог, психолог или врач может помочь разобраться с проблемами, которые продолжаются и влияют на отношения. Обращение за помощью не означает провал пары.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 45, title: 'Практикуйте активное слушание', text: 'Не перебивайте, перескажите своими словами, что услышали, и задайте уточняющий вопрос. Сначала постарайтесь понять партнёра, а уже потом объясняйте свою позицию.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 46, title: 'Не бойтесь говорить «мне не понравилось»', text: 'Говорите конкретно и мягко: что именно было неприятно и что можно изменить. Такая обратная связь помогает сделать близость безопаснее и приятнее.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 47, title: 'Заботьтесь об эмоциональной близости вне спальни', text: 'Разговоры, поддержка, совместные дела и внимание в течение дня создают основу для расслабления и доверия во время интимной близости.', womenRating: 9, menRating: 6 },
{ level: 9, rank: 48, title: 'Изучайте собственное тело', text: 'Понимание того, какие прикосновения, давление и темп вам приятны, облегчает разговор с партнёром. Не обязательно иметь готовый ответ на всё — предпочтения могут меняться.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 49, title: 'Не забывайте про зрительный контакт', text: 'Зрительный контакт может усиливать ощущение близости, но не должен быть обязательным. Смотрите друг на друга тогда, когда обоим это комфортно.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 50, title: 'Отмечайте маленькие улучшения', text: 'Замечайте, когда партнёру стало легче говорить о желаниях, просить о паузе или пробовать подходящий формат. Поддержка прогресса укрепляет доверие лучше, чем критика.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 51, title: 'Учитывайте гормональные циклы', text: 'У некоторых женщин желание, настроение, чувствительность и уровень комфорта могут меняться в течение менструального цикла. Это не строгий график: ориентируйтесь на самочувствие и желание конкретной партнёрши.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 52, title: 'Не давите, если партнёр не готов', text: 'Если партнёр не хочет или сомневается, остановитесь без уговоров и обид. Уважение к отказу сохраняет доверие и делает будущие согласия добровольными.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 53, title: 'Заботьтесь о физической форме вместе', text: 'Совместные прогулки, тренировки или другая физическая активность могут улучшать энергию, настроение и уверенность в теле. Выбирайте занятие, которое приятно обоим, без давления на результат.', womenRating: 6, menRating: 7 },
{ level: 9, rank: 54, title: 'Изучайте разные языки любви', text: 'Желание можно выражать не только прикосновениями, но и словами, помощью, подарками или совместным временем. Обсудите, какие проявления заботы каждый из вас воспринимает лучше всего.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 55, title: 'Не откладывайте разговор о неудовлетворённости', text: 'Если что-то регулярно не устраивает, обсудите это спокойно и конкретно, не дожидаясь накопления обиды. Говорите о своих ощущениях и предложениях, а не оценивайте личность партнёра.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 56, title: 'Практикуйте благодарность вслух', text: 'После близости или в обычный день скажите, что именно вам понравилось и за что вы благодарны партнёру. Конкретная тёплая обратная связь помогает понимать друг друга.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 57, title: 'Оставляйте место для спонтанности', text: 'Не каждый момент близости нужно заранее планировать. Если оба неожиданно хотят провести время вместе, оставьте возможность изменить планы без обязательства доводить всё до секса.', womenRating: 7, menRating: 8 },
{ level: 9, rank: 58, title: 'Изучайте технику дыхания', text: 'Медленное спокойное дыхание может снижать напряжение и помогать лучше замечать ощущения. Не задерживайте дыхание и не используйте дыхательные техники, которые вызывают головокружение.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 59, title: 'Не стесняйтесь смеха над неловкостями', text: 'Неловкие звуки, движения или бытовые ситуации случаются у многих. Добрый совместный смех может снять напряжение, если он не направлен на унижение партнёра.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 60, title: 'Обсуждайте результаты обследований открыто', text: 'Разговор о здоровье, анализах и рекомендациях врача помогает принимать совместные решения о защите и близости. Обсуждение не должно превращаться в подозрение или обвинение.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 61, title: 'Практикуйте прелюдию вне спальни', text: 'Поцелуи, комплименты, лёгкие прикосновения и флирт в течение дня могут создать предвкушение. Любой такой жест должен оставлять партнёру свободу не продолжать дальше.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 62, title: 'Не игнорируйте усталость партнёра', text: 'Если партнёр устал, болеет или перегружен, измените планы и предложите отдых, объятия или помощь. Физическое состояние важнее заранее выбранного сценария.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 63, title: 'Заботьтесь о питании и энергии', text: 'Регулярное питание и достаточное количество энергии поддерживают общее самочувствие, но отдельные продукты не гарантируют усиления либидо. При постоянной усталости стоит искать медицинские или психологические причины.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 64, title: 'Практикуйте регулярные check-in разговоры', text: 'Время от времени спрашивайте, что в близости устраивает, что изменилось и чего хотелось бы больше или меньше. Такие короткие разговоры помогают не ждать, пока проблема превратится в конфликт.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 65, title: 'Не бойтесь просить о повторении', text: 'Если действие или прикосновение понравилось, скажите об этом прямо и попросите повторить. Конкретная просьба помогает партнёру лучше понять, что именно было приятно.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 66, title: 'Уважайте разный темп восстановления', text: 'После интенсивного периода близости одному или обоим партнёрам может хотеться спокойного темпа и паузы. Это не обязательно означает охлаждение или шаг назад в отношениях.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 67, title: 'Практикуйте медленный, осознанный секс', text: 'Снижение темпа помогает замечать дыхание, прикосновения и реакцию друг друга. Медленный формат не обязан длиться долго и не является обязательным для каждого раза.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 68, title: 'Изучайте партнёра заново со временем', text: 'Тело, здоровье и предпочтения могут меняться с возрастом и обстоятельствами. Периодически спрашивайте, что сейчас приятно, вместо того чтобы полагаться только на прошлый опыт.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 69, title: 'Не переносите бытовые конфликты в спальню', text: 'Если между партнёрами есть нерешённая ссора, сначала обсудите её или договоритесь о паузе. Близость не должна использоваться как наказание, награда или способ заставить конфликт исчезнуть.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 70, title: 'Практикуйте телесность без цели секса', text: 'Объятия, массаж и поцелуи без обязательного продолжения снижают давление ожиданий. Такой контакт помогает сохранять нежность даже в периоды низкого желания.', womenRating: 8, menRating: 5 },
{ level: 9, rank: 71, title: 'Изучайте книги и материалы вместе', text: 'Достоверные книги и материалы о сексуальном здоровье могут дать паре общий язык для обсуждения желаний, границ и безопасности. Проверяйте источники и не воспринимайте любой совет как универсальный.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 72, title: 'Не забывайте о собственном удовольствии', text: 'Забота о партнёре не должна означать полное игнорирование собственных ощущений. Говорите о том, что приятно вам, и ищите формат, в котором внимание получает каждый.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 73, title: 'Практикуйте честность о фантазиях без реализации', text: 'Можно поделиться фантазией просто для доверительного разговора, без предложения немедленно её воплощать. Фантазия, желание и действие — разные вещи.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 74, title: 'Заботьтесь о комфортной температуре в комнате', text: 'Проветрите комнату, подготовьте плед или отрегулируйте отопление, если кому-то жарко или холодно. Физический комфорт помогает расслабиться и не отвлекаться.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 75, title: 'Не спешите одеваться сразу после', text: 'Если обоим комфортно, останьтесь на несколько минут рядом, обнимаясь или разговаривая. Обнажённость после секса не обязательна: каждый может одеться, принять душ или побыть отдельно.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 76, title: 'Практикуйте разные роли инициатора', text: 'Иногда начинайте близость по очереди, если оба этого хотят, но не превращайте инициативу в обязанность или соревнование. Партнёр всегда может отказаться или предложить другой формат.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 77, title: 'Изучайте, как меняется возбуждение с возрастом', text: 'С возрастом могут меняться скорость возбуждения, чувствительность, естественная смазка и время восстановления. Эти изменения можно учитывать, а при боли или стойких нарушениях обсуждать с врачом.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 78, title: 'Не молчите о боли или дискомфорте', text: 'Сразу скажите о боли, жжении, онемении или неприятном давлении и остановитесь. Дискомфорт не нужно терпеть, а повторяющиеся симптомы требуют консультации врача.', womenRating: 9, menRating: 6 },
{ level: 9, rank: 79, title: 'Практикуйте признание уязвимости', text: 'Разговор о неуверенности, тревоге или страхе оценки может укрепить доверие. Отвечайте на такую откровенность поддержкой, а не шутками и критикой.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 80, title: 'Не откладывайте близость «на потом» бесконечно', text: 'Если желание есть у обоих, постоянное откладывание может закрепить избегание. Обсудите реальные причины усталости и выберите небольшой доступный шаг, но не создавайте обязанность заниматься сексом.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 81, title: 'Заботьтесь о личном пространстве и приватности', text: 'Закройте дверь, выберите подходящее время и убедитесь, что вас не будут неожиданно тревожить. Ощущение безопасности помогает расслабиться и свободнее говорить о границах.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 82, title: 'Практикуйте благодарность за инициативу', text: 'Если партнёр проявил инициативу, скажите, что заметили и цените это, даже если в тот раз не были готовы продолжать. Благодарность не должна превращаться в обещание будущего согласия.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 83, title: 'Изучайте разницу между желанием и возбуждением', text: 'У некоторых людей желание появляется заранее, а у других — постепенно уже после начала безопасной и приятной близости. При этом никто не обязан продолжать, если желание не появилось.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 84, title: 'Не форсируйте оргазм любой ценой', text: 'Попытка обязательно достичь оргазма может усиливать тревогу и отвлекать от ощущений. Разрешите себе остановиться или просто получить удовольствие без конкретного результата.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 85, title: 'Практикуйте нежность в повседневной жизни', text: 'Объятия, поцелуи, прикосновения и слова поддержки без ожидания секса помогают сохранять ощущение связи между интимными вечерами.', womenRating: 9, menRating: 6 },
{ level: 9, rank: 86, title: 'Обсуждайте ожидания от отпуска или поездки', text: 'Перед поездкой поговорите о желаемом темпе отдыха, приватности и времени для пары. Смена обстановки может помочь близости, но не создаёт обязательства заниматься сексом.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 87, title: 'Не игнорируйте влияние лекарств на желание', text: 'Некоторые препараты могут влиять на либидо, возбуждение или оргазм. Расскажите врачу о таких изменениях и не отменяйте лечение самостоятельно.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 88, title: 'Практикуйте паузы в отношениях с гаджетами вечером', text: 'Выделите хотя бы часть вечера без экранов и уведомлений, чтобы уделить внимание разговору, объятиям или совместному отдыху.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 89, title: 'Не бойтесь просить медленнее или быстрее', text: 'Просьба изменить темп — это нормальная обратная связь, а не критика партнёра. Можно использовать короткие фразы или жесты, которые понятны обоим.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 90, title: 'Практикуйте эмпатию к чужим триггерам', text: 'Если определённые темы, слова или прикосновения вызывают у партнёра тревогу, остановитесь и уточните, какая поддержка нужна. Не требуйте подробного объяснения и не проверяйте границы намеренно.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 91, title: 'Изучайте разницу подходов «за» и «после» ссоры', text: 'Некоторым помогает нежность после примирения, а другим нужно сначала побыть отдельно и успокоиться. Обсудите, какой порядок комфортен вашей паре, не используя секс для замены разговора.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 92, title: 'Не забывайте праздновать годовщины близости', text: 'Особая дата может стать поводом вспомнить важные моменты отношений, устроить свидание или поговорить о том, что вы цените друг в друге.', womenRating: 8, menRating: 5 },
{ level: 9, rank: 93, title: 'Практикуйте совместное принятие решений о новом', text: 'Любой новый опыт обсуждайте заранее: что именно предлагается, какие есть границы и как остановить процесс. Решение должно приниматься обоими без давления.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 94, title: 'Изучайте, как стресс на работе влияет на желание', text: 'Рабочая нагрузка может снижать энергию, настроение и интерес к близости. Обсуждайте влияние стресса, чтобы не воспринимать усталость партнёра как личное отвержение.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 95, title: 'Не бойтесь обращаться за консультацией к врачу', text: 'Боль, сухость, проблемы с эрекцией, резкое снижение желания и другие симптомы могут иметь медицинскую причину. Консультация помогает выбрать безопасное решение и не заниматься самолечением.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 96, title: 'Практикуйте благодарность за терпение партнёра', text: 'Отмечайте, когда партнёр уважает ваш темп, границы или период восстановления. Такая благодарность укрепляет доверие, но не создаёт обязанность «отплатить» близостью.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 97, title: 'Не измеряйте близость только количеством раз', text: 'Частота не показывает качество отношений сама по себе. Учитывайте внимание, взаимное удовольствие, безопасность и возможность свободно отказаться.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 98, title: 'Изучайте предпочтения партнёра, а не только свои', text: 'Спрашивайте, что партнёру приятно, замечайте изменения и не считайте его реакцию само собой разумеющейся. Взаимное внимание важнее попытки идеально выполнить заранее выученную технику.', womenRating: 9, menRating: 8 },
{ level: 9, rank: 99, title: 'Практикуйте терпение к разным этапам отношений', text: 'Начальная страсть, периоды усталости и более спокойная зрелая близость могут сменять друг друга. Важно адаптироваться к изменениям и продолжать поддерживать контакт.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 100, title: 'Помните, что близость — это про связь, а не идеальную технику', text: 'Внимание, доверие, согласие и возможность говорить о своих ощущениях важнее безупречного выполнения любых техник.', womenRating: 9, menRating: 8 },  
{ level: 9, rank: 101, title: 'Используйте технику сенсатфокус', text: 'Сенсатфокус — это поочерёдные прикосновения без цели обязательно довести партнёра до оргазма или проникновения. Такая практика помогает сосредоточиться на ощущениях, лучше узнать тело друг друга и снизить давление ожиданий.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 102, title: 'Практикуйте касания без обязательного продолжения', text: 'Заранее договоритесь, что объятия, массаж и другие прикосновения не обязаны переходить в секс. Это помогает сохранить нежность и уменьшить тревогу из-за ожидания продолжения.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 103, title: 'Заведите ритуал еженедельного свидания', text: 'Выделяйте регулярное время только для двоих: прогулка, ужин, разговор или совместное занятие без телефонов и бытовых задач.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 104, title: 'Планируйте короткие «вылазки» без детей', text: 'Даже несколько часов наедине помогают партнёрам переключиться с родительских обязанностей на отношения друг с другом. Заранее договоритесь о безопасном присмотре за детьми.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 105, title: 'Обсуждайте, как совмещать роли родителей и партнёров', text: 'Поговорите о распределении домашних и родительских обязанностей, а также о времени для пары. Явное переключение из бытового режима в личное время помогает не терять эмоциональный контакт.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 106, title: 'Находите сигналы «выключения из родительского режима»', text: 'Создайте небольшой вечерний ритуал, который означает начало времени вдвоём: переодевание, душ, чай или несколько минут разговора без телефонов.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 107, title: 'Заботьтесь о приватности заранее', text: 'Заранее договоритесь с няней или близкими о времени присмотра и убедитесь, что вас не будут неожиданно прерывать. Ощущение приватности снижает тревогу и помогает расслабиться.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 108, title: 'Не откладывайте близость до идеальных условий', text: 'Идеального момента может не наступить из-за усталости, дел и забот. Ищите реалистичный формат, который подходит обоим, но не превращайте близость в обязательное задание.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 109, title: 'Учитывайте влияние изменений после родов', text: 'После родов на желание и комфорт могут влиять гормоны, восстановление тканей, усталость, недосып и новая нагрузка. Не сравнивайте этот период с прежним ритмом и обращайтесь к врачу при боли или других симптомах.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 110, title: 'Восстанавливайте близость постепенно после родов', text: 'Начинайте с разговоров, объятий, поцелуев и других форм нежности, а к проникновению возвращайтесь после восстановления и разрешения врача. Любой дискомфорт — повод остановиться.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 111, title: 'Обсуждайте изменения тела без осуждения', text: 'Тело может меняться после беременности, болезни, стресса или с возрастом. Поддерживайте партнёра словами и действиями, не сравнивайте его с прежним видом и не навязывайте оценок.', womenRating: 9, menRating: 7 },
{ level: 9, rank: 112, title: 'Изучайте, как менопауза влияет на желание', text: 'Во время менопаузы могут меняться желание, чувствительность, естественная смазка и комфорт. Помогают время, лубрикант, адаптация близости и консультация врача при неприятных симптомах.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 113, title: 'Используйте увлажняющие средства при необходимости', text: 'Вагинальные увлажняющие средства могут применяться регулярно при сухости, а лубрикант — непосредственно перед близостью. При боли, жжении или стойком дискомфорте обратитесь к врачу.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 114, title: 'Обсуждайте эректильные сложности спокойно', text: 'Разовый эпизод может быть связан со стрессом, усталостью, алкоголем или тревогой. Избегайте насмешек и давления, а при повторяющихся трудностях предложите обратиться к врачу.', womenRating: 6, menRating: 8 },
{ level: 9, rank: 115, title: 'Изучайте немедикаментозные способы поддержки эрекции', text: 'На эрекцию могут положительно влиять сон, физическая активность, отказ от курения, снижение стресса и лечение хронических заболеваний. Эти меры не заменяют медицинскую помощь при стойкой проблеме.', womenRating: 5, menRating: 7 },
{ level: 9, rank: 116, title: 'Не воспринимайте лекарства как последнее средство', text: 'Медицинская помощь при сексуальных трудностях — обычный рабочий инструмент, а не признак поражения или слабости. Любые препараты следует подбирать с врачом с учётом противопоказаний.', womenRating: 5, menRating: 7 },
{ level: 9, rank: 117, title: 'Учитывайте влияние диабета на чувствительность', text: 'Диабет может влиять на кровообращение, нервы, чувствительность и эректильную функцию. Контроль заболевания и обсуждение симптомов с врачом помогают подобрать безопасную поддержку.', womenRating: 5, menRating: 6 },
{ level: 9, rank: 118, title: 'Обсуждайте побочные эффекты лекарств с врачом', text: 'Некоторые препараты могут снижать желание, возбуждение или способность к оргазму. Врач иногда может изменить схему лечения, но отменять или заменять препарат самостоятельно нельзя.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 119, title: 'Заботьтесь о щитовидной железе', text: 'Нарушения функции щитовидной железы могут влиять на энергию, настроение и сексуальное желание. При соответствующих симптомах обсудите обследование с врачом, а не принимайте гормоны самостоятельно.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 120, title: 'Проходите профилактические осмотры регулярно', text: 'Плановые визиты помогают вовремя обнаруживать заболевания и побочные эффекты лечения, которые могут влиять на желание или физический комфорт.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 121, title: 'Изучайте влияние тревожных расстройств на близость', text: 'Тревога может мешать расслабиться, снижать желание и отвлекать во время близости. Лечение тревожного расстройства и поддержка партнёра часто улучшают интимную сферу.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 122, title: 'Обсуждайте влияние депрессии на желание открыто', text: 'Депрессия может снижать настроение, энергию, интерес и сексуальное желание. Это симптом состояния, а не доказательство потери любви или влечения к партнёру.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 123, title: 'Поддерживайте партнёра в трудные периоды без давления', text: 'Предлагайте присутствие, помощь и спокойный разговор, не требуя немедленно вернуться к прежней активности. Поддержка не должна превращаться в контроль или обязанность выздороветь быстрее.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 124, title: 'Заботьтесь о совместном отдыхе', text: 'Регулярный отдых, сон и время без рабочих или бытовых задач помогают снижать накопленный стресс. Планируйте восстановление так же внимательно, как другие дела.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 125, title: 'Планируйте поездки, ориентированные на пару', text: 'Поездка без привычных бытовых обязанностей может дать больше времени для общения и отдыха. Заранее обсудите бюджет, ожидания, приватность и то, что каждый хочет получить от путешествия.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 126, title: 'Изучайте новое вместе как способ сближения', text: 'Общий курс, хобби или занятие создаёт совместные впечатления и темы для разговора. Эмоциональная близость вне спальни может поддерживать и интимную связь.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 127, title: 'Танцуйте вместе время от времени', text: 'Совместный танец дома или на занятии помогает восстановить телесный контакт, координацию и ощущение игры без обязательного перехода к сексу.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 128, title: 'Готовьте еду вместе как форму близости', text: 'Совместное приготовление еды даёт время для общения, сотрудничества и лёгких прикосновений. Важно соблюдать безопасность на кухне и не превращать процесс в проверку обязанностей.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 129, title: 'Отправляйте партнёру голосовые сообщения с теплом', text: 'Короткое голосовое сообщение с поддержкой, благодарностью или тёплой мыслью может ощущаться личнее текста и поддерживать связь в течение дня.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 130, title: 'Пишите короткие записки без повода', text: 'Оставьте партнёру короткое сообщение вроде «думаю о тебе» или «спасибо за сегодня». Небольшое внимание не требует повода и не создаёт обязательства отвечать так же.', womenRating: 8, menRating: 5 },
{ level: 9, rank: 131, title: 'Делайте небольшие подарки без праздничного повода', text: 'Небольшой подарок или любимая вещь может показать, что вы помните о предпочтениях партнёра. Подарок не должен быть способом купить внимание или заменить разговор.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 132, title: 'Отмечайте годовщину первой встречи', text: 'Используйте дату как повод вспомнить важные события, повторить часть первого свидания или рассказать, что изменилось в ваших чувствах за это время.', womenRating: 8, menRating: 5 },
{ level: 9, rank: 133, title: 'Пересматривайте старые фото и переписки вместе', text: 'Воспоминания о начале отношений могут вернуть тёплые эмоции и показать, какой путь пара прошла. Не сравнивайте прошлое с настоящим как «лучшее» и «хуже».', womenRating: 7, menRating: 5 },
{ level: 9, rank: 134, title: 'Обсуждайте, что изменилось за годы и почему', text: 'Поговорите о том, как изменились ваши потребности, привычки, тело, график и представления о близости. Такое обсуждение помогает принять новый этап вместо попытки вернуть прошлое буквально.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 135, title: 'Не сравнивайте текущий этап с началом отношений', text: 'Начальная страсть основана на новизне, а длительные отношения могут давать больше доверия и спокойствия. Оценивайте нынешнюю близость по вашим текущим потребностям, а не по воспоминаниям.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 136, title: 'Учитывайте разницу темпераментов партнёров', text: 'Партнёры могут различаться по скорости реакций, потребности в общении и уровне активности. Это не доказывает меньшую любовь, но требует понятных договорённостей и уважения к темпу каждого.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 137, title: 'Изучайте стиль привязанности друг друга', text: 'Понимание того, как партнёр переживает близость, дистанцию и конфликт, может уменьшить ошибочные выводы. Используйте такие знания для поддержки, а не для навешивания ярлыков.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 138, title: 'Работайте над доверием постепенно после кризиса', text: 'После серьёзного конфликта доверие восстанавливается через последовательные действия, честность и выполнение договорённостей. Не требуйте мгновенного возвращения прежней близости.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 139, title: 'Не используйте близость как инструмент примирения по умолчанию', text: 'Секс может временно снизить напряжение, но не заменяет признание проблемы и разговор. Сначала выясните, нужна ли партнёру физическая близость или эмоциональная безопасность и время.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 140, title: 'Уважайте разный подход к примирению после ссоры', text: 'Одному партнёру может хотеться обняться сразу, а другому — сначала побыть одному и успокоиться. Оба варианта нормальны, если вы обсуждаете их без наказания и давления.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 141, title: 'Практикуйте прощение без затягивания обид', text: 'Проговорите, что произошло, какие чувства это вызвало и что нужно изменить. Прощение не означает забыть проблему или отказаться от границ, а постоянное молчание может усиливать дистанцию.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 142, title: 'Обсуждайте финансовый стресс отдельно от близости', text: 'Договоритесь о времени для разговора о деньгах, чтобы финансовая тревога не превращалась в постоянные претензии в спальне. Разделение тем помогает сохранить эмоциональную безопасность.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 143, title: 'Заботьтесь о балансе работы и личной жизни', text: 'Обсудите границы рабочего времени, доступность после работы и регулярные периоды без задач. Постоянная занятость одного или обоих партнёров может незаметно вытеснять общение и близость.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 144, title: 'Учитывайте влияние сменного графика работы', text: 'При сменной работе желание может зависеть от сна, усталости и времени суток. Согласуйте короткие окна для общения и нежности, не требуя совпадения с обычным вечерним графиком.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 145, title: 'Синхронизируйте календари заранее', text: 'Общий календарь помогает видеть свободное время, планировать свидания и не воспринимать отсутствие близости как личное отвержение. Планирование оставляет право передумать или перенести встречу.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 146, title: 'Не откладывайте близость только на выходные', text: 'Если оба хотят близости, не обязательно ждать одного свободного дня недели. Небольшие моменты внимания в будни могут снижать давление на выходные и поддерживать связь.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 147, title: 'Разрешайте себе короткие моменты близости в будни', text: 'Пятнадцать минут объятий, поцелуев или массажа могут быть ценными даже без продолжения. Короткий формат не должен восприниматься как «неполноценный» вариант.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 148, title: 'Обсуждайте разные культурные представления о близости', text: 'Семья, культура и воспитание могут влиять на ожидания о ролях, частоте секса и допустимых проявлениях нежности. Переводите общие представления в конкретные договорённости пары.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 149, title: 'Прорабатывайте влияние строгого воспитания на отношение к телу', text: 'Стыд и запреты, усвоенные в детстве, могут влиять на самооценку и способность расслабляться во взрослом возрасте. Помогают безопасная информация, поддержка партнёра и работа с психологом при необходимости.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 150, title: 'Не переносите чужой негативный опыт на свою пару', text: 'Истории друзей, родственников или прошлых отношений могут быть полезны как опыт, но не определяют вашу пару. Оценивайте собственные отношения по реальным договорённостям, ощущениям и поведению.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 151, title: 'Ограничивайте влияние социальных сетей на самооценку', text: 'Публикации о «идеальных» телах и отношениях часто показывают только отобранные моменты. Сравнивайте себя не с лентой, а с собственным самочувствием и реальными договорённостями пары.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 152, title: 'Обсуждайте ожидания от порноконтента честно', text: 'Поговорите о том, какие сцены воспринимаются как фантазия, а какие могут создавать нереалистичные ожидания. Контент не должен становиться обязательным стандартом для вашей близости.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 153, title: 'Следите за балансом потребления откровенного контента', text: 'Обратите внимание, если контент вытесняет желанную близость, мешает возбуждению, сну, работе или вызывает скрытность и конфликты. В таком случае полезно обсудить ситуацию с партнёром или специалистом.', womenRating: 5, menRating: 6 },
{ level: 9, rank: 154, title: 'Обсуждайте комфортные границы соцсетей и переписок', text: 'Заранее договоритесь, что для вашей пары считается флиртом, скрытностью или нарушением границ. Это снижает неопределённость, но не заменяет доверие и уважение приватности.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 155, title: 'Не читайте переписки партнёра без разрешения', text: 'Тайная проверка телефона нарушает приватность и часто усиливает тревогу вместо решения проблемы. Если есть подозрения, обсудите конкретное поведение и свои чувства напрямую.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 156, title: 'Обсуждайте ревность как чувство, а не как обвинение', text: 'Используйте формулировки вроде «я почувствовал тревогу» и описывайте конкретную ситуацию. Это помогает говорить о потребности в безопасности, не объявляя партнёра виновным заранее.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 157, title: 'Разбирайтесь в источниках недоверия вместе', text: 'Ревность может быть связана с прошлым опытом, неуверенностью или реальными нарушениями договорённостей. Разделяйте факты, предположения и чувства, чтобы искать решение без взаимных атак.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 158, title: 'Обсуждайте личные границы с друзьями и родственниками', text: 'Договоритесь, какие темы отношений можно обсуждать с близкими, а какие остаются только между партнёрами. Согласие на раскрытие личной информации важно даже в долгих отношениях.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 159, title: 'Защищайте личное пространство пары от чужого мнения', text: 'Не всем нужно знать детали вашей близости, частоту секса или личные конфликты. Приватность помогает принимать решения по собственным ценностям, а не под давлением окружающих.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 160, title: 'Изучайте технику осознанного дыхания вдвоём', text: 'Перед близостью несколько минут дышите спокойно и синхронно, обращая внимание на ощущения. Не задерживайте дыхание и прекращайте практику при головокружении или дискомфорте.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 161, title: 'Практикуйте медитацию для снижения тревожности', text: 'Короткие практики осознанности могут помогать замечать тревожные мысли и возвращать внимание к текущему моменту. Это дополнительный инструмент, а не замена лечению тревожного расстройства.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 162, title: 'Изучайте упражнения Кегеля для укрепления мышц', text: 'Упражнения тазового дна могут улучшать контроль мочеиспускания и некоторые аспекты сексуальной функции. Перед регулярной практикой важно научиться не только напрягать, но и полностью расслаблять мышцы.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 163, title: 'Обсуждайте состояние здоровья тазового дна', text: 'После родов, операций, боли, недержания или ощущения чрезмерного напряжения стоит обратиться к врачу или физиотерапевту тазового дна. Самостоятельные упражнения подходят не во всех случаях.', womenRating: 7, menRating: 4 },
{ level: 9, rank: 164, title: 'Заботьтесь о регулярной физической активности', text: 'Прогулки, тренировки и другая посильная активность поддерживают кровообращение, настроение, энергию и уверенность в теле. Выбирайте нагрузку с учётом здоровья и без наказания за пропуски.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 165, title: 'Следите за качеством сна обоих партнёров', text: 'Недосып может снижать энергию, желание и терпение в общении. Обсудите режим, распределение ночных обязанностей и время для восстановления.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 166, title: 'Ограничивайте кофеин ближе к вечеру', text: 'Кофеин во второй половине дня может мешать некоторым людям заснуть и расслабиться. Ориентируйтесь на собственную чувствительность, а не на обязательный полный отказ.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 167, title: 'Следите за гидратацией организма', text: 'Достаточное употребление воды поддерживает общее самочувствие и энергию, особенно при жаре или физической активности. Сильная жажда, головокружение и слабость — повод сначала заняться состоянием организма.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 168, title: 'Обсуждайте влияние курения на возбуждение', text: 'Курение ухудшает состояние сосудов и может влиять на эрекцию, возбуждение и общее самочувствие. Поддержка при отказе от курения полезнее критики и давления.', womenRating: 5, menRating: 6 },
{ level: 9, rank: 169, title: 'Изучайте влияние веса на энергию и уверенность', text: 'Обсуждайте не соответствие внешнему стандарту, а самочувствие, подвижность и уровень энергии. Изменения веса должны быть безопасными и не строиться на стыде или критике тела.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 170, title: 'Поддерживайте партнёра в заботе о теле без критики', text: 'Спросите, какая поддержка нужна партнёру, и уважайте его темп. Конкретная помощь и признание усилий обычно полезнее замечаний о внешности.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 171, title: 'Обсуждайте шрамы и изменения тела с теплом', text: 'Шрамы и другие изменения тела являются частью личной истории, а не недостатком. Слушайте реакцию партнёра и не прикасайтесь к чувствительной зоне без разрешения.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 172, title: 'Заботьтесь о партнёре после операций терпеливо', text: 'После операции приоритетом остаются заживление, обезболивание и рекомендации врача. Возвращайтесь к прикосновениям и близости постепенно, начиная с того, что не вызывает боли или нагрузки.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 173, title: 'Изучайте адаптации близости при хронической боли', text: 'Обсудите время суток, положения, опоры и длительность, которые уменьшают боль. При новых или усиливающихся симптомах сначала нужна консультация врача.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 174, title: 'Учитывайте особенности близости при инвалидности', text: 'Обсуждайте возможности, ограничения, помощь, удобные положения и способы остановить процесс. Не делайте предположений: ориентируйтесь на слова и самостоятельные решения самого партнёра.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 175, title: 'Не считайте секс единственным мерилом отношений', text: 'Качество пары также проявляется в доверии, заботе, уважении, поддержке, совместных решениях и способности безопасно обсуждать сложные темы.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 176, title: 'Развивайте невербальную нежность', text: 'Взгляд, прикосновение к руке, объятие или поцелуй могут выражать близость без слов. Учитывайте реакцию партнёра и не воспринимайте любой жест как согласие на продолжение.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 177, title: 'Практикуйте комплименты не только о внешности', text: 'Отмечайте характер, чувство юмора, заботу, надёжность и поступки партнёра. Это поддерживает самооценку и показывает, что его ценность не ограничивается внешностью.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 178, title: 'Отмечайте усилия партнёра в быту', text: 'Благодарите за конкретную помощь, организацию дел и заботу о семье. Признание вклада снижает ощущение незаметной нагрузки и поддерживает эмоциональную близость.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 179, title: 'Делите бытовые обязанности справедливо', text: 'Обсудите не только список дел, но и время, внимание и ответственность за их выполнение. Ощущение несправедливости может снижать желание сильнее, чем отдельная ссора.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 180, title: 'Обсуждайте усталость честно вместо молчаливого отказа', text: 'Скажите, что вы устали и какая форма близости сейчас возможна: объятия, разговор, отдых или перенос на другое время. Честность лучше, чем согласие через силу или холодное отвержение.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 181, title: 'Предлагайте альтернативы вместо полного отказа', text: 'Если вы не готовы к сексу, можно предложить объятия, массаж, поцелуи или совместный отдых — только если этого действительно хочется. Альтернатива не должна становиться обязательством.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 182, title: 'Практикуйте «да» без обязательства идти до конца', text: 'Согласие на поцелуи, прикосновения или начало близости не означает согласие на весь сценарий. Любой партнёр может остановиться или изменить решение в любой момент.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 183, title: 'Обсуждайте, что делать при разном уровне энергии вечером', text: 'Заранее договоритесь о вариантах: короткая нежность, перенос на утро, совместный отдых или полноценная близость при готовности обоих. Компромисс не должен означать постоянную уступку одного человека.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 184, title: 'Пробуйте близость по утрам как альтернативу', text: 'Если вечером мешает усталость, обсудите утро или другое время, когда энергии больше. Утренняя близость возможна только после пробуждения и при ясном желании обоих.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 185, title: 'Изучайте свои пики энергии в течение дня', text: 'Наблюдайте, когда вам легче расслабиться и когда обычно появляется желание. Это помогает выбирать подходящее время без попытки подстроиться под универсальный график.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 186, title: 'Не привязывайте самооценку к частоте близости', text: 'Количество секса не определяет привлекательность человека, силу любви или ценность отношений. Оценивайте себя по более широким признакам самочувствия и качества связи.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 187, title: 'Обсуждайте статистику как ориентир, а не норму', text: 'Средние показатели помогают увидеть разнообразие, но не задают обязательный ритм. Здоровой можно считать ту частоту, которая добровольно и комфортно подходит вашей паре.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 188, title: 'Не стесняйтесь спрашивать совета у специалистов', text: 'Психолог, сексолог, врач или физиотерапевт может помочь разобраться с конкретной трудностью. Выбирайте специалиста с профильной подготовкой и не заменяйте медицинскую помощь непроверенными советами.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 189, title: 'Читайте проверенные материалы, а не форумы наугад', text: 'Ищите информацию в материалах медицинских организаций, профильных специалистов и научных источниках. Форумы могут содержать личный опыт, но не заменяют диагностику и рекомендации врача.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 190, title: 'Проходите совместные курсы или воркшопы для пар', text: 'Структурированные занятия могут помочь обсудить общение, границы и близость в безопасной обстановке. Выбирайте программу с понятной квалификацией ведущих и добровольным участием.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 191, title: 'Используйте приложения для пар с осторожностью', text: 'Приложения могут помогать с идеями, календарём и разговорами, но не должны превращать близость в обязательный план или собирать лишние личные данные.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 192, title: 'Ведите личный дневник ощущений при желании', text: 'Записывайте настроение, уровень стресса, сон и собственные ощущения, если это помогает замечать закономерности. Дневник остаётся личным, если вы не договорились делиться им добровольно.', womenRating: 5, menRating: 4 },
{ level: 9, rank: 193, title: 'Обсуждайте итоги пройденных экспериментов', text: 'После нового опыта спросите, что понравилось, что вызвало сомнения и стоит ли повторять это. Разговор не должен превращаться в оценку или требование продолжать.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 194, title: 'Признавайте, когда что-то не подошло, без вины', text: 'Эксперимент может не понравиться даже при хорошей подготовке. Это не означает провал партнёра или отношений, а даёт полезную информацию о ваших границах.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 195, title: 'Не заставляйте себя повторять неприятный опыт', text: 'Боль, тревога или сильный дискомфорт — достаточная причина отказаться от повторения. Не нужно доказывать любовь, смелость или открытость через действие, которое вам не подходит.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 196, title: 'Обсуждайте желания заново раз в несколько месяцев', text: 'Периодически проверяйте, что по-прежнему приятно, что изменилось и появились ли новые границы. Предпочтения не обязаны оставаться одинаковыми на протяжении отношений.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 197, title: 'Заводите общий список идей для экспериментов', text: 'Записывайте идеи, которые можно обсудить позже, и отмечайте уровень готовности каждого. Такой список помогает выбирать новое без давления в моменте.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 198, title: 'Обсуждайте разницу между «хочу попробовать» и «хочу регулярно»', text: 'Интерес к разовому опыту не означает желание сделать его постоянной частью близости. Сразу разделяйте пробу, регулярную практику и фантазию для обсуждения.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 199, title: 'Уважайте право партнёра передумать', text: 'Согласие, данное заранее, можно отменить в любой момент. После слова «стоп» действие прекращается без споров, обид и попыток уговорить продолжить.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 200, title: 'Заканчивайте вечер близости тёплым разговором', text: 'После близости спросите, как партнёр себя чувствует, поблагодарите друг друга и обсудите, что было приятно. Разговор может быть коротким, но он помогает сохранить эмоциональный контакт.', womenRating: 9, menRating: 6 },
{ level: 9, rank: 201, title: 'Практикуйте объятия дольше обычного', text: 'Если партнёру комфортно, задержитесь в объятиях ещё на несколько секунд и обратите внимание на дыхание и ощущения. Объятия должны оставаться добровольными, а не способом удержать человека.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 202, title: 'Изучайте технику медленного возбуждения', text: 'Постепенно наращивайте близость через разговор, поцелуи, прикосновения и паузы без резких переходов. Ориентируйтесь на реакцию обоих, а не на обязательный финальный результат.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 203, title: 'Обсуждайте комфортную громкость и открытость звуков', text: 'Заранее или в процессе обсудите, насколько свободно вам комфортно выражать эмоции голосом. Учитывайте приватность помещения и не требуйте от партнёра звучать определённым образом.', womenRating: 6, menRating: 7 },
{ level: 9, rank: 204, title: 'Не стесняйтесь просить конкретное движение', text: 'Короткая просьба вроде «чуть левее», «медленнее» или «не останавливайся» помогает партнёру точнее понять ваши ощущения. Такая обратная связь не является критикой.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 205, title: 'Обсуждайте предпочтения по силе давления при ласках', text: 'Скажите, какие прикосновения приятны: лёгкие, уверенные или переменной силы. Начинайте мягче и увеличивайте давление только после понятной положительной реакции.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 206, title: 'Изучайте карту чувствительности партнёра заново со временем', text: 'Проверяйте, что нравится партнёру сейчас, потому что ощущения могут меняться из-за возраста, стресса, здоровья или жизненных обстоятельств. Не полагайтесь только на прошлый опыт.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 207, title: 'Не бойтесь тишины во время близости', text: 'Паузы без слов могут быть естественной частью близости. Не заставляйте себя разговаривать, но сохраняйте возможность спокойно сообщить о комфорте, дискомфорте или желании остановиться.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 208, title: 'Практикуйте благодарность себе, а не только партнёру', text: 'Разрешайте себе получать удовольствие, отдыхать и отказываться без чувства долга. Забота о собственных границах помогает строить более взаимную близость.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 209, title: 'Обсуждайте личные комплексы бережно и по обоюдному желанию', text: 'Поделитесь неуверенностью только тогда, когда готовы к такому разговору. Партнёр должен выслушать без насмешек, советов без просьбы и попыток обесценить чувства.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 210, title: 'Не требуйте от партнёра читать мысли', text: 'Даже внимательный партнёр не может точно угадывать желания, границы и изменения настроения. Говорите прямо о том, что вам приятно, неудобно или нужно изменить.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 211, title: 'Практикуйте регулярные объятия без сексуального подтекста', text: 'Объятия и другие прикосновения без ожидания секса поддерживают тепло и снижают давление. Перед объятием учитывайте настроение и желание партнёра к физическому контакту.', womenRating: 8, menRating: 5 },
{ level: 9, rank: 212, title: 'Изучайте, как усталость влияет именно на вас двоих', text: 'Замечайте, как недосып, нагрузка и стресс меняют желание и терпение каждого. Это помогает заранее выбирать отдых, короткую нежность или перенос близости без обид.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 213, title: 'Обсуждайте план на вечер заранее в загруженные недели', text: 'В начале недели договоритесь, когда сможете побыть вдвоём и какой формат подойдёт. План должен помогать найти время, но не превращаться в обязанность заниматься сексом.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 214, title: 'Не воспринимайте план как потерю спонтанности навсегда', text: 'Запланированная близость и спонтанные моменты могут существовать одновременно. Планирование лишь помогает учитывать реальную нагрузку и доступное время.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 215, title: 'Изучайте способы быстро переключиться из рабочего режима', text: 'Короткий ритуал — душ, смена одежды, прогулка, музыка или несколько минут разговора — помогает завершить рабочий день и сосредоточиться на партнёре.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 216, title: 'Обсуждайте влияние экрана перед сном на близость', text: 'Уведомления, новости и поздний просмотр контента могут мешать расслаблению и сну. Обсудите время отключения экранов без взаимных обвинений.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 217, title: 'Создавайте «зону без гаджетов» в спальне', text: 'Оставляйте телефоны за пределами спальни или включайте режим «не беспокоить», если это удобно обоим. Исключение можно сделать для экстренной связи.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 218, title: 'Изучайте влияние яркого и тёплого освещения на настроение', text: 'Выбирайте освещение, при котором обоим комфортно видеть друг друга и расслабляться. Тёплый приглушённый свет может нравиться одним людям, а другим подходит обычное яркое освещение.', womenRating: 7, menRating: 5 },
{ level: 9, rank: 219, title: 'Экспериментируйте с ароматами в спальне', text: 'Используйте только запахи, которые приятны обоим, и проветривайте комнату. Сильный аромат может вызвать головную боль или аллергическую реакцию, поэтому не применяйте его как обязательный элемент.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 220, title: 'Обсуждайте комфортную температуру постели заранее', text: 'Учитывайте, кому жарко, кому холодно, и подготовьте одеяла или проветривание. Небольшой физический дискомфорт может мешать расслаблению сильнее, чем кажется.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 221, title: 'Держите под рукой всё необходимое заранее', text: 'Подготовьте лубрикант, презервативы, полотенце, воду и другие нужные вещи, чтобы не прерывать близость. Средства должны быть доступными, чистыми и подходящими для ситуации.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 222, title: 'Обновляйте запасы смазки и защиты регулярно', text: 'Проверяйте срок годности, целостность упаковки и условия хранения презервативов и лубриканта. Повреждённые или просроченные средства использовать не следует.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 223, title: 'Изучайте разные типы лубрикантов', text: 'Лубриканты на водной, силиконовой и гибридной основе отличаются ощущениями, стойкостью и совместимостью. Выбор зависит от презерватива, игрушки и конкретной практики.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 224, title: 'Проверяйте совместимость смазки с игрушками и презервативами', text: 'Масла могут повреждать латекс, а некоторые силиконовые смазки — силиконовые игрушки. Перед использованием прочитайте инструкции производителя обоих изделий.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 225, title: 'Храните игрушки в чистоте и порядке', text: 'Очищайте игрушки до и после использования способом из инструкции, полностью высушивайте и храните отдельно от пыли и материалов, которые могут повредить поверхность.', womenRating: 5, menRating: 5 },
{ level: 9, rank: 226, title: 'Выбирайте игрушки из безопасных материалов', text: 'Отдавайте предпочтение изделиям с понятным составом, инструкцией и гладкой поверхностью без повреждений. Непористые материалы обычно проще очищать, но проверяйте рекомендации производителя.', womenRating: 6, menRating: 5 },
{ level: 9, rank: 227, title: 'Обсуждайте новую игрушку до покупки вместе', text: 'Посмотрите характеристики, размер, функции и правила ухода, а затем убедитесь, что оба готовы попробовать. Совместный выбор снижает риск давления и разочарования.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 228, title: 'Не воспринимайте игрушку как замену партнёру', text: 'Игрушка может быть дополнением к совместному удовольствию или личной практике. Обсудите ожидания заранее и не используйте её как доказательство недостаточности партнёра.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 229, title: 'Изучайте реакцию партнёра на новое без спешки с выводами', text: 'Первая попытка может сопровождаться неловкостью или непривычными ощущениями. Дайте время, спросите о самочувствии и не повторяйте опыт, если партнёр не хочет.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 230, title: 'Обсуждайте комфортный уровень интенсивности заранее', text: 'Определите, какой диапазон давления, скорости и громкости подходит каждому. Начинайте с меньшей интенсивности и увеличивайте её только при понятном согласии.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 231, title: 'Договаривайтесь о стоп-слове при любых экспериментах', text: 'Выберите короткий сигнал, который означает немедленную остановку без споров. Убедитесь, что оба партнёра слышат его и готовы прекратить действие сразу.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 232, title: 'Практикуйте плавный выход из ролевых игр', text: 'После завершения сценария назовите друг друга обычными именами, снимите реквизит, поговорите и предложите объятия или другое комфортное проявление заботы.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 233, title: 'Обсуждайте личные триггеры до ролевых игр', text: 'Заранее скажите, какие темы, слова, действия или образы могут вызывать тревогу. Не используйте известные триггеры в игре и договоритесь о безопасной альтернативе.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 234, title: 'Не путайте фантазию с реальным желанием', text: 'То, что интересно представить, может не подходить для воплощения. Обсуждайте фантазию отдельно от действия и не воспринимайте признание как согласие попробовать.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 235, title: 'Уважайте разный темп раскрепощения партнёров', text: 'Один партнёр может быстрее соглашаться на эксперименты, а другому нужно больше времени. Начинайте с общего комфортного уровня и не подталкивайте к ускорению.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 236, title: 'Хвалите партнёра за смелость попробовать новое', text: 'Отметьте доверие и открытость партнёра, даже если эксперимент оказался неудачным. Похвала не должна означать, что он обязан повторять опыт.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 237, title: 'Не иронизируйте над неудачным экспериментом', text: 'Если что-то не получилось, обсудите это спокойно и без насмешек. Уместный юмор возможен только тогда, когда партнёр сам чувствует себя спокойно.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 238, title: 'Обсуждайте разницу в желаемой частоте новизны', text: 'Одному партнёру могут подходить редкие изменения, а другому — более частые эксперименты. Договоритесь о темпе, который не превращает новизну в обязанность.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 239, title: 'Совмещайте привычное и новое в одном сценарии', text: 'Оставьте знакомые элементы, которые нравятся обоим, и добавьте только одну новую деталь. Такой подход помогает снизить тревогу и понять, что именно подошло.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 240, title: 'Отмечайте прогресс в открытости за годы отношений', text: 'Вспоминайте, о чём вам было трудно говорить раньше и что теперь обсуждается легче. Это помогает замечать рост доверия, не сравнивая себя с другими парами.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 241, title: 'Не давите на партнёра ожиданиями «идеальной» пары', text: 'Фотографии и рассказы в социальных сетях показывают только выбранную часть жизни. Оценивайте отношения по реальному комфорту, доверию и договорённостям, а не по внешнему образу.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 242, title: 'Обсуждайте, что лично для вас означает «хорошая близость»', text: 'Для одного это может быть нежность, для другого — страсть, разговор, разнообразие или чувство безопасности. Сверьте ожидания и не принимайте собственное определение за универсальное.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 243, title: 'Признавайте вклад друг друга в развитие близости', text: 'Отмечайте инициативу, честность, терпение и готовность учиться с обеих сторон. Ответственность за атмосферу отношений не должна лежать только на одном партнёре.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 244, title: 'Не бойтесь быть неидеальными вместе', text: 'Неловкость, ошибки, смех и необходимость остановиться бывают частью реальной близости. Важнее способность поддержать друг друга и спокойно скорректировать ситуацию.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 245, title: 'Практикуйте самоиронию в неловкие моменты', text: 'Добрая самоирония может снизить напряжение, если не направлена на тело, способности или уязвимость партнёра. При сильном дискомфорте лучше сделать паузу, а не шутить.', womenRating: 7, menRating: 7 },
{ level: 9, rank: 246, title: 'Обсуждайте долгосрочные ожидания от сексуальной жизни', text: 'Говорите о том, как на близость могут влиять дети, возраст, здоровье, переезды и работа. Такие разговоры помогают заранее искать адаптации, а не воспринимать изменения как неожиданную угрозу.', womenRating: 6, menRating: 6 },
{ level: 9, rank: 247, title: 'Инвестируйте в отношения так же, как в другие сферы жизни', text: 'Время, внимание, забота и обучение поддерживают отношения так же, как тренировки поддерживают здоровье. Регулярные небольшие действия обычно эффективнее редких масштабных жестов.', womenRating: 7, menRating: 6 },
{ level: 9, rank: 248, title: 'Возвращайтесь к базовым советам при затруднениях', text: 'Если сложный эксперимент не помог, вернитесь к основам: разговору, согласию, комфорту, лубриканту, защите и вниманию к реакции партнёра.', womenRating: 8, menRating: 7 },
{ level: 9, rank: 249, title: 'Празднуйте маленькие моменты близости, а не только большие', text: 'Цените объятия утром, тёплое сообщение, совместный душ, разговор или прикосновение среди дня. Близость складывается из регулярных небольших проявлений, а не только из особенных вечеров.', womenRating: 8, menRating: 6 },
{ level: 9, rank: 250, title: 'Помните, что развитие близости — это путь, а не финальная точка', text: 'Желания, здоровье, обстоятельства и границы могут меняться, поэтому интимная жизнь пары развивается постоянно. Важны готовность обсуждать изменения, уважать согласие и искать подходящий формат вместе.', womenRating: 9, menRating: 8 },
];
